SELECT cdscode
FROM frpm
WHERE "Enrollment (K-12)" > 500;

SELECT CAST(SUM(CASE WHEN status = 'C' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS pct_running_ok
FROM loan
WHERE amount < 100000;

SELECT CAST(SUM(CASE WHEN a.element = 'cl' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS pct_chlorine
FROM atom a
WHERE a.molecule_id IN (
    SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '-'
);

SELECT DISTINCT fd.type
FROM foreign_data fd
WHERE fd.language = 'German' AND fd.type IS NOT NULL;

SELECT s.name
FROM sets s
WHERE EXISTS (
    SELECT 1 FROM set_translations st
    WHERE st.setcode = s.code AND st.language = 'Korean'
)
AND NOT EXISTS (
    SELECT 1 FROM set_translations st
    WHERE st.setcode = s.code AND st.language = 'Japanese'
);

SELECT SUM(cost) AS total_pizza_cost
FROM expense
WHERE expense_description ILIKE '%pizza%';
